        "a": "본성의 빛과 창조 및 섭리의 사역들이 하나님의 선하심과 지혜와 권능을 분명히 나타내어 사람으로 하여금 핑계할 수 없게 하나, 구원에 이르게 하는 하나님과 그의 뜻에 대한 지식을 주기에는 불충분합니다. 그러므로 주께서는 자신의 교회를 위하여 진리를 계시하시고 기록하게 하셨으니, 이것이 곧 신구약 성경 66권이며, 신앙과 삶의 최종 규범입니다.",
