        "a": "오직 살아 계시고 참되신 한 하나님만이 계시며, 그분은 존재와 완전성에 있어 무한하시며, 순수한 영이시며, 보이지 않으시고, 불변하시며, 영원하시고, 전능하시며, 지극히 지혜로우시고 거룩하십니다. 이 신격의 단일체 안에 본질과 권능과 영원성이 동등하신 삼위, 곧 하나님 성부, 하나님 성자, 하나님 성령이 계십니다.",
