        "a": "사나 죽으나 나는 나의 것이 아니요, 몸도 영혼도 나의 신실하신 구주 예수 그리스도의 것입니다. 주께서는 자신의 보배로운 피로 나의 모든 죄값을 완전히 치르셨고, 나를 마귀의 모든 권세에서 해방하셨습니다. 또한 하늘에 계신 나의 아버지의 뜻이 아니면 머리털 하나도 땅에 떨어지지 않도록 나를 보존하시며, 실로 모든 것이 합력하여 나의 구원을 이루도록 하십니다. 그러므로 주께서는 성령으로 말미암아 나에게 영생을 확신시켜 주시고, 이제부터는 진심으로 주를 위하여 살기를 원하고 준비되게 하십니다.",
